<?php $discovery=Serp::saved($wid,'backlink_discovery');$checks=[];foreach(rows("SELECT name,value FROM website_settings WHERE website_id=? AND name LIKE 'backlink_check_%'",[$wid]) as $item)$checks[(int)substr($item['name'],15)]=json_decode($item['value'],true)?:[];$linksToCheck=rows('SELECT id,source_url,target_url FROM backlinks WHERE website_id=? ORDER BY id DESC LIMIT 100',[$wid]);?>
<section class="ranking-hero"><div><span class="eyebrow">BACKLINK CHECKER</span><h2>Verify the links pointing to your website.</h2><p>Check saved source pages for your target link, its anchor text and follow attributes.</p></div><button class="button" data-action="backlink-discover" data-website-id="<?=$wid?>">Find referring-page candidates</button></section>
<section class="card stack"><div class="card-header"><div><h3>Live backlink verification</h3><p class="small">Add a source URL and target URL below, then verify it here. Checks inspect public HTML; blocked pages remain unverified.</p></div></div><div class="table-wrap"><table><thead><tr><th>Source page</th><th>Last verification</th><th>Result</th><th>Action</th></tr></thead><tbody><?php foreach($linksToCheck as $link):$check=$checks[$link['id']]??[];?><tr><td><a class="ranking-url" href="<?=e($link['source_url'])?>" target="_blank" rel="noopener noreferrer"><?=e($link['source_url'])?></a></td><td><?=e($check['checked_at']??'Not checked')?></td><td><span class="badge"><?=e($check['state']??'Unverified')?></span><p class="small"><?=e($check['message']??'')?></p></td><td><button class="button secondary small-button" data-action="backlink-check" data-website-id="<?=$wid?>" data-id="<?=$link['id']?>">Check link</button></td></tr><?php endforeach;?></tbody></table></div><?php if(!$linksToCheck)empty_state('Add your first source page','Use the backlink form below or search for referring-page candidates.');?></section>
<?php if($discovery):?><section class="card stack"><h3>Referring-page candidates</h3><p class="small">Google search results from <?=e($discovery['date'])?>. These are possible mentions, not a complete backlink index. “Verify and add” checks for a link to your project homepage.</p><?php foreach($discovery['candidates'] as $i=>$candidate):?><article class="issue"><div class="card-header"><a class="ranking-url" href="<?=e($candidate['url'])?>" target="_blank" rel="noopener noreferrer"><?=e($candidate['title']?:$candidate['url'])?></a><button class="button secondary small-button" data-action="backlink-add-candidate" data-website-id="<?=$wid?>" data-index="<?=$i?>">Verify and add</button></div><p class="small"><?=e($candidate['snippet'])?></p></article><?php endforeach;if(!$discovery['candidates'])empty_state('No candidates returned','You can still add known source pages and verify their links.');?></section><?php endif;?>
